"""
Permission request/response utilities for hook-based permission routing.

The PreToolUse hook writes permission requests to ~/.qbraid/permissions/.
This module provides functions to read those requests and write responses,
used by the CLI watch command and frontend handlers.
"""

import json
import logging
import time
from pathlib import Path
from typing import Any, Generator, Optional

from .constants import PERMISSIONS_DIR

logger = logging.getLogger(__name__)

_PERMS_DIR = Path(PERMISSIONS_DIR)


def _safe_session_filename(session_id: str, suffix: str) -> Path:
    """Build a safe filename under _PERMS_DIR, preventing path traversal."""
    # Strip any path separators or parent references
    safe_id = Path(session_id).name
    if not safe_id or safe_id in (".", ".."):
        raise ValueError(f"Invalid session_id: {session_id!r}")
    return _PERMS_DIR / f"{safe_id}{suffix}"


def get_pending_request(session_id: str) -> Optional[dict[str, Any]]:
    """Check if there's a pending permission request for a session.

    Returns the request dict if found, None otherwise.
    """
    request_file = _safe_session_filename(session_id, ".request.json")
    if not request_file.exists():
        return None

    try:
        return json.loads(request_file.read_text())
    except (json.JSONDecodeError, IOError):
        return None


def respond_to_request(session_id: str, decision: str, reason: str = "") -> bool:
    """Write a permission response for a session.

    Args:
        session_id: The session to respond to.
        decision: "allow", "deny", or "ask".
        reason: Optional reason (shown to the user on deny).

    Returns:
        True if the response was written successfully.
    """
    _PERMS_DIR.mkdir(parents=True, exist_ok=True)
    response_file = _safe_session_filename(session_id, ".response.json")

    response = {
        "decision": decision,
        "reason": reason,
        "timestamp": time.time(),
    }

    try:
        response_file.write_text(json.dumps(response))
        return True
    except IOError as e:
        logger.warning("Failed to write permission response: %s", e)
        return False


def start_watching(session_id: str) -> None:
    """Signal that someone is watching this session for permissions.

    Creates a ``.watching`` file that the PreToolUse hook checks.
    If this file exists, the hook will write permission requests
    and wait for responses. If absent, the hook falls through to
    Claude's native permission UI immediately.
    """
    _PERMS_DIR.mkdir(parents=True, exist_ok=True)
    watching_file = _safe_session_filename(session_id, ".watching")
    watching_file.write_text(str(time.time()))
    logger.debug("Started watching permissions for session %s", session_id)


def stop_watching(session_id: str) -> None:
    """Signal that nobody is watching this session anymore.

    Removes the ``.watching`` file and cleans up any pending requests.
    """
    watching_file = _safe_session_filename(session_id, ".watching")
    watching_file.unlink(missing_ok=True)

    # Clean up any stale request/response files
    for suffix in (".request.json", ".response.json"):
        f = _safe_session_filename(session_id, suffix)
        f.unlink(missing_ok=True)

    logger.debug("Stopped watching permissions for session %s", session_id)


def watch_permission_requests(
    session_id: str,
    poll_interval: float = 0.5,
) -> Generator[dict[str, Any], None, None]:
    """Yield permission requests as they appear for a session.

    Polls the permissions directory for new request files.
    Yields the request dict when found.
    """
    while True:
        request = get_pending_request(session_id)
        if request:
            yield request
        time.sleep(poll_interval)


# ---------------------------------------------------------------------------
# Unified permission interface (routes to Claude file-based or OpenCode HTTP)
# ---------------------------------------------------------------------------


def get_pending_permissions(
    session_id: str,
    tool: str = "",
    port: Optional[int] = None,
    native_session_id: Optional[str] = None,
) -> list[dict[str, Any]]:
    """Get all pending permission requests for a session.

    Unified interface that routes to the right backend:
    - Claude/Codex: file-based (.request.json)
    - OpenCode: HTTP API (GET /permission)

    Args:
        session_id: Session ID (qBraid UUID or native).
        tool: Tool identifier ("claude", "codeq", "codex").
        port: OpenCode HTTP port (required for codeq).
        native_session_id: OpenCode's native session ID (ses_XXXX)
            for filtering permissions to the correct session.

    Returns:
        List of permission request dicts, each with at minimum:
        ``tool_name``, ``summary``, and ``request_id``.
    """
    results = []

    # OpenCode: use HTTP API
    if tool == "codeq" and port:
        try:
            from .opencode_api import list_pending_permissions

            for perm in list_pending_permissions(port):
                # Filter to the correct session if native_session_id provided
                perm_sid = perm.get("sessionID", "")
                if native_session_id and perm_sid != native_session_id:
                    continue
                results.append(
                    {
                        "request_id": perm.get("id", ""),
                        "session_id": perm.get("sessionID", session_id),
                        "tool_name": perm.get("permission", "tool"),
                        "summary": ", ".join(perm.get("patterns", [])),
                        "metadata": perm.get("metadata", {}),
                        "always_patterns": perm.get("always", []),
                        "source": "opencode_api",
                        "port": port,
                    }
                )
        except Exception as e:
            logger.debug("Error getting OpenCode permissions: %s", e)

    # Claude/Codex: file-based
    else:
        request = get_pending_request(session_id)
        if request:
            results.append(
                {
                    "request_id": session_id,
                    "session_id": session_id,
                    "tool_name": request.get("tool_name", ""),
                    "summary": request.get("summary", ""),
                    "metadata": request.get("tool_input", {}),
                    "source": "file",
                }
            )

    return results


def respond_to_permission(
    session_id: str,
    request_id: str,
    decision: str,
    reason: str = "",
    tool: str = "",
    port: Optional[int] = None,
) -> bool:
    """Respond to a permission request.

    Unified interface that routes to the right backend.

    Args:
        session_id: Session ID.
        request_id: Permission request ID (from get_pending_permissions).
        decision: "allow", "deny", or "ask".
        reason: Optional reason for denial.
        tool: Tool identifier.
        port: OpenCode HTTP port.

    Returns:
        True if the response was sent successfully.
    """
    # OpenCode: use HTTP API
    if tool == "codeq" and port:
        try:
            from .opencode_api import reply_to_permission

            reply_map = {"allow": "once", "always": "always", "deny": "reject", "ask": "reject"}
            return reply_to_permission(port, request_id, reply_map.get(decision, "once"))
        except Exception as e:
            logger.debug("Error responding to OpenCode permission: %s", e)
            return False

    # Claude/Codex: file-based
    return respond_to_request(session_id, decision, reason)
